define('ltiTestReview/review/plugins/navigation/review-panel/panel-data',['lodash', 'i18n'], function (_, __) {
  'use strict';
  var compareByPosition = (a, b) => a.position - b.position;
  var getItemType = (item, withScore) => {
    if (withScore) {
      if (item.informational) {
        return 'info';
      }
      if (item.isExternallyScored && item.pendingExternalScore) {
        return 'score-pending';
      }
      if (item.maxScore && item.score > 0 && item.score === item.maxScore) {
        return 'correct';
      }
      if (item.maxScore && item.score === 0) {
        return 'incorrect';
      }
      if (item.maxScore && item.score > 0 && item.score < item.maxScore) {
        return 'score-partial';
      }
      return 'no-score';
    } else {
      if (item.informational) {
        return 'info';
      }
      if (item.skipped) {
        return 'skipped';
      }
      return 'default';
    }
  };
  var extractData = (entry, withScore) => {
    var {
      id,
      label,
      position,
      informational,
      skipped,
      title,
      unseen,
      score,
      maxScore
    } = entry || {};
    var data = {
      id,
      label,
      position,
      withScore
    };
    if (withScore) {
      Object.assign(data, {
        score,
        maxScore
      });
    }
    if ('undefined' !== typeof informational) {
      data.informational = informational;
    }
    if ('undefined' !== typeof skipped) {
      data.skipped = skipped;
    }
    if ('undefined' !== typeof unseen) {
      data.unseen = unseen;
    }
    if ('undefined' !== typeof title) {
      data.title = title;
    }
    return data;
  };
  var extendReviewItemScope = (item, entry, numericLabel) => {
    var reviewItem = Object.assign({}, entry);
    var type = reviewItem.type;
    reviewItem.numericLabel = type === 'info' ? '' : "".concat(numericLabel);
    reviewItem.icon = type === 'info' ? 'info' : null;
    reviewItem.ariaLabel = type === 'info' ? __('Informational item') : __('Question %s', reviewItem.numericLabel);
    reviewItem.scoreType = null;
    if (type === 'correct') {
      reviewItem.scoreType = 'correct';
    } else if (type === 'incorrect') {
      reviewItem.scoreType = 'incorrect';
    } else if (type === 'score-pending') {
      reviewItem.scoreType = 'score-pending';
    } else if (type === 'score-partial') {
      reviewItem.scoreType = 'score-partial';
    }
    if (reviewItem.unseen) {
      reviewItem.status = 'unseen';
    } else if (type !== 'info' && type !== 'skipped') {
      reviewItem.status = 'answered';
    } else {
      reviewItem.status = 'viewed';
    }
    reviewItem.accordionScoreLabel = '-';
    if (['correct', 'incorrect', 'score-partial', 'score-pending'].includes(reviewItem.type) && item.maxScore) {
      reviewItem.accordionScoreLabel = "".concat(item.score || 0, "/").concat(item.maxScore);
    }
    return reviewItem;
  };
  return {
    getReviewPanelMap(testMap, withScore) {
      var {
        parts,
        score,
        maxScore
      } = testMap;
      var items = new Map();
      var sections = new Map();
      var nonInformationalCount = 0;
      var panelMap = {
        parts: _.map(parts, part => Object.assign(extractData(part, withScore), {
          sections: _.map(part.sections, section => {
            var reviewSection = Object.assign(extractData(section, withScore), {
              items: _.chain(section.items).sortBy('position').map(item => {
                var reviewItem = extractData(item, withScore);
                reviewItem.type = getItemType(item, withScore);
                if (reviewItem.type !== 'info') {
                  nonInformationalCount++;
                }
                reviewItem = extendReviewItemScope(item, reviewItem, nonInformationalCount);
                items.set(item.id, reviewItem);
                return reviewItem;
              }).value()
            });
            sections.set(section.id, reviewSection);
            return reviewSection;
          }).sort(compareByPosition)
        })).sort(compareByPosition),
        withScore,
        items,
        sections
      };
      if (withScore) {
        Object.assign(panelMap, {
          score,
          maxScore
        });
      }
      return panelMap;
    }
  };
});
