define('ltiTestReview/review/plugins/navigation/next-prev/plugin',['lodash', 'util/shortcut', 'util/namespace', 'core/promiseTimeout', 'taoTests/runner/plugin', 'taoQtiTest/runner/helpers/map', 'ltiTestReview/review/plugins/navigation/next-prev/buttons'], function (_, shortcut, namespaceHelper, promiseTimeout, pluginFactory, mapHelper, buttonsFactory) {
  'use strict';
  return pluginFactory({
    name: 'next-prev',
    init() {
      var testRunner = this.getTestRunner();
      var testConfig = testRunner.getConfig();
      var pluginShortcuts = (testConfig.shortcuts || {})[this.getName()] || {};
      if (testConfig.allowShortcuts) {
        Object.keys(pluginShortcuts).forEach(key => {
          shortcut.add(namespaceHelper.namespaceAll(pluginShortcuts[key], this.getName(), true), () => testRunner.trigger("nav-".concat(key), true), {
            avoidInput: true,
            prevent: true
          });
        });
      }
      this.disable();
      testRunner.on('enablenav', () => this.enable()).on('disablenav', () => this.disable()).on('hidenav', () => this.hide()).on('shownav', () => this.show()).on('destroy', () => shortcut.remove(".".concat(this.getName())));
    },
    render() {
      return promiseTimeout(new Promise(resolve => {
        var testRunner = this.getTestRunner();
        var buttons = buttonsFactory(this.getAreaBroker().getNavigationArea());
        var canDoNext = () => {
          var last = _.findLast(mapHelper.getJumps(testRunner.getTestMap()), jump => jump && jump.identifier);
          var context = testRunner.getTestContext();
          return last && context.itemPosition < last.position;
        };
        var canDoPrevious = () => {
          var first = _.find(mapHelper.getJumps(testRunner.getTestMap()), jump => jump && jump.identifier);
          var context = testRunner.getTestContext();
          return first && context.itemPosition > first.position;
        };
        var doNext = () => {
          if (this.getState('enabled') !== false && canDoNext()) {
            testRunner.trigger('disablenav');
            testRunner.next();
          }
        };
        var doPrevious = () => {
          if (this.getState('enabled') !== false && canDoPrevious()) {
            testRunner.trigger('disablenav');
            testRunner.previous();
          }
        };
        var toggle = () => {
          buttons.toggleButton('prev', canDoPrevious());
          buttons.toggleButton('next', canDoNext());
        };
        buttons.on('click', btn => testRunner.trigger("nav-".concat(btn))).on('ready', () => {
          if (this.getState('enabled') === false) {
            buttons.disable();
          }
          resolve();
        });
        testRunner.on('loaditem testmapchange', toggle).on('nav-next', doNext).on('nav-prev', doPrevious).on("plugin-show.".concat(this.getName()), () => buttons.show()).on("plugin-hide.".concat(this.getName()), () => buttons.hide()).on("plugin-enable.".concat(this.getName()), () => buttons.enable()).on("plugin-disable.".concat(this.getName()), () => buttons.disable()).on("plugin-destroy.".concat(this.getName()), () => buttons.destroy());
      }));
    }
  });
});
